/// <summary>
/// This is a contract class
/// CB197_salesOrderReturnsAndClaims
/// </summary>
[  
    DataContract,
    SysOperationContractProcessing(classStr(METReturnOrderDispositionCodeUpdUIBuilder))
]
final class METReturnOrderDispositionCodeUpdContract extends METSysOperationTaskDataContract implements SysOperationValidatable
{
    str                     packedQuery;
    ReturnDispositionCodeId returnDispositionCodeId;
    guid                    topPickingProcessId;


}

Method.Source:
/// <summary>
/// get/set Disposition code id.
/// </summary>
/// <param name = "_returnDispositionCodeId">Disposition code id</param>
/// <returns>Disposition code id</returns>
[DataMember,
    SysOperationLabel(literalStr('@MET:DispositionCodeForLines'))]
public ReturnDispositionCodeId parmDispositionCode(ReturnDispositionCodeId _returnDispositionCodeId = returnDispositionCodeId)
{
    returnDispositionCodeId = _returnDispositionCodeId;
    return returnDispositionCodeId;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

/// <summary>
/// Gets/set packed query.
/// </summary>
/// <param name = "_packedQuery">Packed query.</param>
/// <returns>Packed query.</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METReturnOrders))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Validates the report parameters.
/// </summary>
/// <returns>true if no errors; otherwise, false.</returns>
public boolean validate()
{
    if (!this.parmDispositionCode())
    {          
        throw error("Please select disposition code for the lookup");
    }

    return true;
}
